CREATE TABLE IF NOT EXISTS public.roadmap_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, current_band NUMERIC(2,1) NOT NULL, target_band NUMERIC(2,1) NOT NULL, exam_date DATE, daily_minutes INTEGER NOT NULL, preferred_skills TEXT[] NOT NULL DEFAULT '{}', level TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.roadmap_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), plan_id UUID NOT NULL REFERENCES public.roadmap_plans(id) ON DELETE CASCADE, week_number INTEGER NOT NULL, scheduled_date DATE NOT NULL, skill TEXT NOT NULL, title TEXT NOT NULL, title_vi TEXT NOT NULL, module_url TEXT NOT NULL, minutes INTEGER NOT NULL, priority SMALLINT NOT NULL DEFAULT 1, completed_at TIMESTAMPTZ, rescheduled_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.daily_tasks ADD COLUMN IF NOT EXISTS roadmap_item_id UUID REFERENCES public.roadmap_items(id) ON DELETE SET NULL;
ALTER TABLE public.roadmap_plans ENABLE ROW LEVEL SECURITY; ALTER TABLE public.roadmap_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own roadmap plans" ON public.roadmap_plans FOR ALL USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE POLICY "Own roadmap items" ON public.roadmap_items FOR ALL USING (EXISTS (SELECT 1 FROM public.roadmap_plans p WHERE p.id=plan_id AND p.user_id=auth.uid()));
